// Grammar-compressed tag runs (Section 4 of the paper, "Grammar-compressing the runs"): the sequence of
// the runs' tags is generated by a RePair-style grammar, encoded as in Gagie et al., "Practical random
// access to SLP-compressed texts" (SPIRE 2020), as in KATKA's gtag.hpp: symbols are grouped by expansion
// length (in runs) and named by (length, offset in their group), so expansion lengths come for free;
// within a group, rules are sorted by the length of their left child, and each sub-group (length, left
// length) stores its rules' children's offsets in fixed widths.  Terminals form the group of length 1,
// with offset = tag.  The top-level sequence is stored as the run at which each of its symbols starts
// (Elias-Fano) plus their offsets.
//
// The grammar comes either from bigrepair -i (prefix.R, prefix.C), as in KATKA, or from repair() below,
// which replaces, in rounds, every pair whose frequency is at least half the largest (greedily, left to
// right) until no pair occurs twice: an approximation of RePair that is fast and needs about 16 bytes
// per run.
#pragma once
#include "bits.hpp"
#include <algorithm>

namespace katka {

struct grammar_rules {
    uint32_t alpha = 0;                                   // terminals 0..alpha-1
    std::vector<std::pair<uint32_t, uint32_t>> rules;     // rule i is symbol alpha + i
    std::vector<uint32_t> C;                              // the top-level sequence
};

inline grammar_rules repair(const std::vector<uint32_t> &seq, uint32_t alpha) {
    grammar_rules G; G.alpha = alpha; G.C = seq;
    std::vector<uint64_t> pairs;
    for (int round = 0;; ++round) {
        std::vector<uint32_t> &s = G.C;
        if (s.size() < 4) break;
        pairs.resize(s.size() - 1);
        for (size_t i = 0; i + 1 < s.size(); ++i) pairs[i] = (uint64_t)s[i] << 32 | s[i + 1];
        std::sort(pairs.begin(), pairs.end());
        uint64_t maxf = 0;
        for (size_t a = 0; a < pairs.size();) { size_t b = a; while (b < pairs.size() && pairs[b] == pairs[a]) ++b; maxf = std::max<uint64_t>(maxf, b - a); a = b; }
        if (maxf < 2) break;
        uint64_t thr = std::max<uint64_t>(2, maxf / 2);
        std::vector<std::pair<uint64_t, uint32_t>> chosen;        // pair -> new symbol
        for (size_t a = 0; a < pairs.size();) {
            size_t b = a; while (b < pairs.size() && pairs[b] == pairs[a]) ++b;
            if (b - a >= thr) {
                uint32_t x = (uint32_t)(pairs[a] >> 32), y = (uint32_t)pairs[a];
                chosen.push_back({pairs[a], alpha + (uint32_t)G.rules.size()});
                G.rules.push_back({x, y});
            }
            a = b;
        }
        std::vector<uint64_t>().swap(pairs);
        size_t o = 0, i = 0;
        uint64_t replaced = 0;
        while (i < s.size()) {
            if (i + 1 < s.size()) {
                uint64_t key = (uint64_t)s[i] << 32 | s[i + 1];
                auto it = std::lower_bound(chosen.begin(), chosen.end(), std::make_pair(key, 0u));
                if (it != chosen.end() && it->first == key) { s[o++] = it->second; i += 2; ++replaced; continue; }
            }
            s[o++] = s[i++];
        }
        s.resize(o);
        if (!replaced) break;
        // drop rules that were never used (a pair can lose all its occurrences to overlapping ones)
    }
    // remove unused rules and renumber, keeping children before parents
    const uint64_t S = alpha + G.rules.size();
    std::vector<char> used(S, 0);
    for (uint32_t x : G.C) used[x] = 1;
    for (uint64_t r = G.rules.size(); r-- > 0;)
        if (used[alpha + r]) { used[G.rules[r].first] = 1; used[G.rules[r].second] = 1; }
    std::vector<uint32_t> nid(S);
    for (uint32_t t = 0; t < alpha; ++t) nid[t] = t;
    std::vector<std::pair<uint32_t, uint32_t>> nr;
    for (uint64_t r = 0; r < G.rules.size(); ++r)
        if (used[alpha + r]) { nid[alpha + r] = alpha + (uint32_t)nr.size(); nr.push_back({nid[G.rules[r].first], nid[G.rules[r].second]}); }
    G.rules.swap(nr);
    for (auto &x : G.C) x = nid[x];
    return G;
}

// reads bigrepair -i output: prefix.R (alphabet size, then rule pairs, 32-bit) and prefix.C (top level)
inline grammar_rules read_bigrepair(const std::string &prefix) {
    grammar_rules G;
    FILE *fr = open_or_die(prefix + ".R", "rb");
    int32_t a; rd(fr, a); G.alpha = (uint32_t)a;
    int32_t p[2];
    while (fread(p, 4, 2, fr) == 2) G.rules.push_back({(uint32_t)p[0], (uint32_t)p[1]});
    fclose(fr);
    FILE *fc = open_or_die(prefix + ".C", "rb");
    int32_t x;
    while (fread(&x, 4, 1, fc) == 1) G.C.push_back((uint32_t)x);
    fclose(fc);
    return G;
}

struct tag_grammar {
    uint64_t rho = 0;
    uint32_t maxlen = 0;
    std::vector<uint32_t> grp;                // expansion length -> group (0 = terminals; UINT32_MAX = none)
    std::vector<uint32_t> gfirst;             // group -> first sub-group
    struct Sub { uint32_t start, left; uint64_t bit; uint8_t wl, wr; };
    std::vector<Sub> subs;
    std::vector<uint64_t> bits;               // children's offsets, packed
    EliasFano CB;                             // the run at which each top-level symbol starts
    PackedInts Coff;                          // offsets of the top-level symbols in their groups
    static inline thread_local std::vector<std::pair<uint32_t, uint32_t>> stk;

    static inline uint64_t getbits(const std::vector<uint64_t> &w, uint64_t pos, unsigned width) {
        if (width == 0) return 0;
        uint64_t i = pos >> 6, o = pos & 63, v = w[i] >> o;
        if (o + width > 64) v |= w[i + 1] << (64 - o);
        return width == 64 ? v : v & ((1ULL << width) - 1);
    }
    inline void children(uint32_t l, uint32_t o, uint32_t &ll, uint32_t &lo, uint32_t &ro) const {
        uint32_t g = grp[l], a = gfirst[g], b = gfirst[g + 1];
        while (b - a > 1) { uint32_t m = (a + b) / 2; if (subs[m].start <= o) a = m; else b = m; }
        const Sub &s = subs[a]; uint64_t p = s.bit + (uint64_t)(o - s.start) * (s.wl + s.wr);
        ll = s.left; lo = (uint32_t)getbits(bits, p, s.wl); ro = (uint32_t)getbits(bits, p + s.wl, s.wr);
    }
    uint64_t top_len(uint64_t k, uint64_t st) const { return (k + 1 < Coff.size() ? CB.access(k + 1) : rho) - st; }
    // calls f(tag) for runs a, a+1, ..., a+cnt-1 (cnt >= 1)
    template <class F> inline void decode(uint64_t a, uint64_t cnt, F f) const {
        uint64_t k = CB.count_less(a + 1) - 1, st = CB.access(k), off = a - st;
        uint32_t l = (uint32_t)top_len(k, st), o = (uint32_t)Coff[k];
        auto &S = stk; S.clear();
        uint32_t ll, lo, ro;
        while (l > 1) { children(l, o, ll, lo, ro); if (off < ll) { S.push_back({l - ll, ro}); l = ll; o = lo; } else { off -= ll; l -= ll; o = ro; } }
        f(o);
        while (--cnt) {
            if (S.empty()) { ++k; st = CB.access(k); l = (uint32_t)top_len(k, st); o = (uint32_t)Coff[k]; }
            else { l = S.back().first; o = S.back().second; S.pop_back(); }
            while (l > 1) { children(l, o, ll, lo, ro); S.push_back({l - ll, ro}); l = ll; o = lo; }
            f(o);
        }
    }
    uint64_t bytes() const {
        return grp.size() * 4 + gfirst.size() * 4 + subs.size() * sizeof(Sub) + bits.size() * 8 + CB.bytes() + Coff.bytes();
    }
    void save(FILE *f) const { wr(f, rho); wr(f, maxlen); wvec(f, grp); wvec(f, gfirst); wvec(f, subs); wvec(f, bits); CB.save(f); Coff.save(f); }
    void load(FILE *f) { rd(f, rho); rd(f, maxlen); rvec(f, grp); rvec(f, gfirst); rvec(f, subs); rvec(f, bits); CB.load(f); Coff.load(f); }

    void build(const grammar_rules &Gr) {
        const uint32_t alpha = Gr.alpha;
        const uint64_t R = Gr.rules.size(), S = alpha + R;
        std::vector<uint32_t> len(S, 1);
        maxlen = 1;
        for (uint64_t i = 0; i < R; ++i) {
            if (Gr.rules[i].first >= alpha + i || Gr.rules[i].second >= alpha + i) throw std::runtime_error("grammar: rules out of order");
            len[alpha + i] = len[Gr.rules[i].first] + len[Gr.rules[i].second];
            maxlen = std::max(maxlen, len[alpha + i]);
        }
        std::vector<uint64_t> gsz(maxlen + 1, 0);
        for (uint64_t i = 0; i < R; ++i) gsz[len[alpha + i]]++;
        grp.assign(maxlen + 1, UINT32_MAX); grp[1] = 0;
        uint32_t ng = 1;
        for (uint32_t l = 2; l <= maxlen; ++l) if (gsz[l]) grp[l] = ng++;
        gsz[1] = alpha;
        auto width = [&](uint32_t l) { uint64_t s = gsz[l]; unsigned b = 0; while ((1ULL << b) < s) ++b; return (uint8_t)b; };
        std::vector<uint32_t> ord(R);
        for (uint64_t i = 0; i < R; ++i) ord[i] = (uint32_t)i;
        std::sort(ord.begin(), ord.end(), [&](uint32_t x, uint32_t y) {
            uint32_t lx = len[alpha + x], ly = len[alpha + y];
            if (lx != ly) return lx < ly;
            uint32_t ax = len[Gr.rules[x].first], ay = len[Gr.rules[y].first];
            return ax != ay ? ax < ay : x < y; });
        std::vector<uint32_t> off(S);
        for (uint32_t t = 0; t < alpha; ++t) off[t] = t;
        for (uint64_t i = 0; i < R;) {
            uint32_t l = len[alpha + ord[i]]; uint64_t j = i;
            while (j < R && len[alpha + ord[j]] == l) { off[alpha + ord[j]] = (uint32_t)(j - i); ++j; }
            i = j;
        }
        subs.clear(); gfirst.assign(ng + 1, 0); bits.clear();
        uint64_t pos = 0;
        subs.push_back({0, 0, 0, 0, 0});          // group 0 (terminals): a dummy sub-group
        uint32_t gcur = 0;
        auto put = [&](uint64_t v, unsigned w) {
            if (w == 0) return;
            uint64_t idx = pos >> 6, o = pos & 63;
            if (bits.size() <= idx + 1) bits.resize(idx + 2, 0);
            bits[idx] |= v << o; if (o + w > 64) bits[idx + 1] |= v >> (64 - o);
            pos += w;
        };
        for (uint64_t i = 0; i < R;) {
            uint32_t r0 = ord[i], l = len[alpha + r0], ll = len[Gr.rules[r0].first], g = grp[l];
            while (gcur < g) gfirst[++gcur] = (uint32_t)subs.size();
            Sub s{off[alpha + r0], ll, pos, width(ll), width(l - ll)};
            subs.push_back(s);
            uint64_t j = i;
            while (j < R && len[alpha + ord[j]] == l && len[Gr.rules[ord[j]].first] == ll) {
                uint32_t r = ord[j]; put(off[Gr.rules[r].first], s.wl); put(off[Gr.rules[r].second], s.wr); ++j;
            }
            i = j;
        }
        while (gcur < ng) gfirst[++gcur] = (uint32_t)subs.size();
        bits.resize(pos / 64 + 2);
        rho = 0;
        std::vector<uint64_t> starts;
        starts.reserve(Gr.C.size());
        for (uint32_t x : Gr.C) { starts.push_back(rho); rho += len[x]; }
        CB.build(starts, rho + 1);
        std::vector<uint64_t> co(Gr.C.size());
        for (size_t t = 0; t < Gr.C.size(); ++t) co[t] = off[Gr.C[t]];
        Coff.build(co);
    }
};

}  // namespace katka
